CREATE TABLE IF NOT EXISTS taskNotifications (id INT PRIMARY KEY AUTO_INCREMENT, taskId INT NOT NULL, userId INT NOT NULL, notificationType VARCHAR(100), isRead BOOLEAN DEFAULT false, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_task_notification (taskId));
CREATE TABLE IF NOT EXISTS emailVerificationTokens (id INT PRIMARY KEY AUTO_INCREMENT, userId INT NOT NULL, token VARCHAR(255) NOT NULL UNIQUE, expiresAt DATETIME NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rememberMeTokens (id INT PRIMARY KEY AUTO_INCREMENT, userId INT NOT NULL, tokenHash VARCHAR(255) NOT NULL UNIQUE, expiresAt DATETIME NOT NULL, revokedAt DATETIME, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_user_remember (userId), INDEX idx_remember_expiry (expiresAt));

